(()=>{const m=4,r=i=>{if(!i)return;const s=getComputedStyle(i),l=parseFloat(s.lineHeight)||22,h=l*m+parseFloat(s.paddingTop||0)+parseFloat(s.paddingBottom||0);i.style.height='auto';i.style.height=`${Math.min(i.scrollHeight,h)}px`;i.style.overflowY=i.scrollHeight>h?'auto':'hidden';i.scrollTop=i.scrollHeight};document.querySelectorAll('#toolSearch,#followUpInput').forEach(i=>{r(i);i.addEventListener('input',()=>r(i));i.addEventListener('focus',()=>requestAnimationFrame(()=>{r(i);i.scrollTop=i.scrollHeight}));i.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();i.closest('form')?.requestSubmit()}});i.closest('form')?.addEventListener('submit',()=>setTimeout(()=>r(i),0))})})();
